let db = freshState();
db.role = 'editor';
const publicState = { search:'', category:'', tag:'', page:1, pageSize:6 };
const dialog = document.getElementById('editor-dialog');
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const slugify = value => value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
async function api(path, options={}) {
 const headers = new Headers(options.headers || {});
 if (options.body) headers.set('content-type','application/json');
 if (accessToken) headers.set('authorization',`Bearer ${accessToken}`);
 const response = await fetch(`/api/${path}`,{...options,headers});
 const payload = await response.json().catch(()=>({error:'Resposta inválida do servidor.'}));
 if (!response.ok) { const error = new Error(payload.error || 'Não foi possível concluir a operação.'); error.status=response.status; throw error; }
 return payload;
}
function save() {
 const snapshot = JSON.stringify({...db,role:'editor'});
 saveQueue = saveQueue.catch(()=>{}).then(async()=>{
  if(!accessToken)throw new Error('Sua sessão expirou. Entre novamente para continuar.');
  const payload=await api('content',{method:'POST',body:snapshot});
  return payload;
 });
 saveQueue.catch(error=>{
  if(error.status===401){accessToken='';adminReady=false;localStorage.removeItem(TOKEN_KEY);renderLogin(panelState.tab);return;}
  toast(`Não foi possível salvar: ${error.message}`);
 });
 return saveQueue;
}
async function hydrateContent(withAdmin=false) {
 const payload=await api('content');
 db={...freshState(),...payload,role:'editor'};
 adminReady=withAdmin;
}
const author = id => db.authors.find(a => a.id===id) || {id:'',name:'Equipe Jogo de Cintura',title:'Redação',bio:'',avatar:'JC'};
const published = () => db.articles.filter(a => a.status==='publicado').sort((a,b)=>b.date.localeCompare(a.date));
const dateBR = date => new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(`${date}T12:00:00Z`));
const statusLabel = status => ({rascunho:'Rascunho','em revisão':'Em revisão',aprovado:'Aprovado',devolvido:'Devolvido',publicado:'Publicado',agendado:'Agendado'}[status]||status);
const statusClass = status => slugify(status);
const icon = name => ({search:'<circle cx="11" cy="11" r="7"/><path d="m16 16 4 4"/>',arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',book:'<path d="M4 5.5A2.5 2.5 0 0 1 6.5 3H20v17H6.5A2.5 2.5 0 0 1 4 17.5z"/><path d="M4 6v12M8 7h8M8 11h7"/>',plus:'<path d="M12 5v14M5 12h14"/>',check:'<path d="m5 12 4 4L19 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',chev:'<path d="m9 18 6-6-6-6"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M5.6 9a7 7 0 0 1 11.7-2L20 12M4 12l2.7 5a7 7 0 0 0 11.7-2"/>'})[name]||'<circle cx="12" cy="12" r="8"/>';
const ico = name => `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icon(name)}</svg>`;
function toast(message){ const el=document.getElementById('toast'); el.textContent=message; el.classList.add('show'); clearTimeout(toast.timer); toast.timer=setTimeout(()=>el.classList.remove('show'),2800); }
function routeTo(value){ location.hash=value; }
function brand(){ return `<a class="brand" href="#" aria-label="Jogo de Cintura — início"><img src="assets/logo.png" alt="Jogo de Cintura — Ideias em movimento"></a>`; }
function topbar(){ return `<header class="site-header"><div class="header-inner">${brand()}<nav class="main-nav" aria-label="Navegação principal"><a href="#categoria/tecnologia">Tecnologia</a><a href="#categoria/negocios">Negócios</a><a href="#categoria/carreira">Carreira</a><a href="#categoria/trabalho">Trabalho</a></nav><div class="header-actions"><a class="editor-link" href="#painel">Área editorial <span aria-hidden="true">↗</span></a><button class="mobile-menu" aria-label="Abrir navegação" aria-expanded="false">${ico('menu')}</button></div></div></header>`; }
function storyCard(a, index=0){ const au=author(a.authorId); return `<article class="story-card story-card-${index%3}"><a class="story-image" href="#artigo/${esc(a.slug)}"><img src="${esc(a.cover)}.webp" alt="${esc(a.alt)}" loading="lazy"><span class="photo-category">${esc(a.category)}</span></a><div class="story-copy"><div class="story-meta"><span>${esc(a.category)}</span><span aria-hidden="true">·</span><time datetime="${esc(a.date)}">${dateBR(a.date)}</time></div><h3><a href="#artigo/${esc(a.slug)}">${esc(a.title)}</a></h3><p>${esc(a.excerpt)}</p><div class="story-byline"><a href="#autor/${esc(au.id)}">${esc(au.name)}</a><span>${a.minutes} min de leitura</span></div></div></article>`; }
