function footer(){return `<footer class="site-footer"><div class="footer-top">${brand()}<p>Ideias em movimento.<br><span>Trabalho, negócios e o que vem depois.</span></p><a class="back-top" href="#main">Voltar ao início ↑</a></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Jogo de Cintura.</span><a href="#painel">Área editorial</a><span>Feito para ler, pensar e virar o jogo.</span></div></footer>`;}
function bindHome(){
 const search=document.getElementById('search-input'); search?.addEventListener('input',e=>{publicState.search=e.target.value;publicState.page=1;renderHome();const n=document.getElementById('search-input');n.focus();n.setSelectionRange(n.value.length,n.value.length);});
 document.querySelectorAll('[data-category]').forEach(b=>b.addEventListener('click',()=>{publicState.category=b.dataset.category;publicState.tag='';publicState.page=1;renderHome();}));
 document.querySelectorAll('[data-tag]').forEach(b=>b.addEventListener('click',()=>{publicState.tag=publicState.tag===b.dataset.tag?'':b.dataset.tag;publicState.category='';publicState.page=1;renderHome();}));
 document.getElementById('tag-filter')?.addEventListener('change',e=>{publicState.tag=e.target.value;publicState.category='';publicState.page=1;renderHome();});
 document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>{publicState.page=Number(b.dataset.page);renderHome();document.getElementById('explore-title').scrollIntoView({behavior:'smooth'});}));
 document.getElementById('clear-filters')?.addEventListener('click',()=>{publicState.search='';publicState.category='';publicState.tag='';publicState.page=1;renderHome();});
 document.querySelector('.mobile-menu')?.addEventListener('click',e=>{const nav=document.querySelector('.main-nav');const open=nav.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open);});
}
