 const a=db.articles.find(x=>x.slug===slug&&x.status==='publicado'); if(!a){renderNotFound();return;}
 const au=author(a.authorId);document.title=a.seoTitle||`${a.title} | Jogo de Cintura`;document.querySelector('meta[name="description"]').content=a.seoDescription||a.excerpt;
  const related=published().filter(x=>x.id!==a.id&&(x.category===a.category||x.tags.some(t=>a.tags.includes(t)))).slice(0,3);
 document.getElementById('app').innerHTML=`${topbar()}<main id="main" class="article-page"><nav class="breadcrumbs" aria-label="Trilha de navegação"><a href="#">Início</a>${ico('chev')}<a href="#categoria/${slugify(a.category)}">${esc(a.category)}</a>${ico('chev')}<span>Matéria</span></nav><header class="article-heading"><div class="article-topline"><span class="article-category">${esc(a.category)}</span><span>${a.minutes} min de leitura</span></div><h1>${esc(a.title)}</h1><p class="article-subtitle">${esc(a.subtitle)}</p><div class="article-author-row"><a class="author-avatar" href="#autor/${esc(au.id)}">${esc(au.avatar)}</a><span><strong><a href="#autor/${esc(au.id)}">${esc(au.name)}</a></strong><small>${esc(au.title)} · Publicado em <time datetime="${esc(a.date)}">${dateBR(a.date)}</time></small></span><button class="share-button" id="share-article">Compartilhar ${ico('arrow')}</button></div></header><figure class="article-cover"><img src="${esc(a.cover)}.webp" alt="${esc(a.alt)}"><figcaption>Imagem editorial produzida para a pauta · Jogo de Cintura</figcaption></figure><div class="article-layout"><aside class="article-aside"><span class="aside-label">Nesta matéria</span><a href="#corpo">Leitura completa</a><span class="aside-label">Assuntos</span><div class="article-tags">${a.tags.map(t=>`<button data-tag="${esc(t)}"># ${esc(t)}</button>`).join('')}</div><div class="aside-author"><span class="author-avatar">${esc(au.avatar)}</span><strong>${esc(au.name)}</strong><small>${esc(au.title)}</small><a href="#autor/${esc(au.id)}">Mais matérias do autor ${ico('arrow')}</a></div></aside><article class="article-body" id="corpo">${a.body.map((section,i)=>`<section><h2>${esc(section[0])}</h2>${section.slice(1).map(p=>`<p>${esc(p)}</p>`).join('')}${i===0?`<blockquote>“O que muda de verdade começa quando a tecnologia encontra o trabalho real.”</blockquote>`:''}</section>`).join('')}<div class="article-endmark">✳</div><div class="article-share-bottom"><span>Esta conversa continua.</span><button class="share-button" id="share-article-bottom">Compartilhar ${ico('arrow')}</button></div></article></div><section class="related-section"><div class="section-kicker"><span>Continue por aqui</span><span class="kicker-line"></span></div><h2>Mais ideias em movimento</h2><div class="story-grid">${related.map((x,i)=>storyCard(x,i)).join('')}</div></section></main>${footer()}`;
 document.querySelectorAll('.article-tags [data-tag]').forEach(b=>b.addEventListener('click',()=>{publicState.tag=b.dataset.tag;publicState.category='';publicState.page=1;routeTo('#');setTimeout(()=>document.getElementById('explore-title')?.scrollIntoView(),80);}));
 for(const id of ['share-article','share-article-bottom']) document.getElementById(id)?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(location.href);toast('Link copiado para compartilhar.');}catch{toast('Copie o endereço desta página para compartilhar.');}});
