const panelState={tab:'visao',status:'todos',search:''};
const actorName=()=> 'Segundo Almeida';
const roleText=()=> 'Editor responsável';
function visibleToRole(a){if(db.role==='autor')return a.authorId==='bia-santos';if(db.role==='revisor')return a.status==='em revisão';return true;}
function canEdit(a){return db.role==='editor'||(db.role==='autor'&&a.authorId==='bia-santos'&&['rascunho','devolvido'].includes(a.status));}
function changeStatus(a,status,comment=''){
 const previous=a.status;a.status=status;a.history=a.history||[];a.history.push({status,by:actorName(),at:new Date().toISOString()});
 if(comment.trim()){a.comments=a.comments||[];a.comments.push({by:actorName(),at:new Date().toISOString(),text:comment.trim()});}
 save();toast(`Status atualizado: ${statusLabel(previous)} → ${statusLabel(status)}.`);renderPanel(panelState.tab);
}
function panelTop(){return `<header class="panel-top">${brand()}<div class="panel-heading"><span class="eyebrow">Central de publicação</span><strong>Jogo de Cintura <span>/</span> Painel editorial</strong></div><a class="public-preview" href="#">Ver portal público ${ico('arrow')}</a></header>`;}
function panelNav(){const items=[['visao','Visão geral'],['artigos','Matérias'],['revisoes','Fila de revisão'],['autores','Autores'],['taxonomias','Categorias e tags'],['fluxo','Fluxo editorial']];return `<nav class="panel-sidebar" aria-label="Menu do painel"><div class="sidebar-label">ESPAÇO EDITORIAL</div>${items.map(([id,label])=>`<a href="#painel/${id}" class="side-link ${panelState.tab===id?'selected':''}" ${panelState.tab===id?'aria-current="page"':''}><span class="side-dot side-${id}"></span>${label}${id==='revisoes'?`<b>${roleArticles().filter(a=>a.status==='em revisão').length}</b>`:''}</a>`).join('')}<div class="sidebar-bottom"><span class="sidebar-label">CONTA</span><a class="sidebar-public" href="#">← Voltar ao portal</a><button class="reset-button" id="logout-button">${ico('refresh')} Encerrar sessão</button></div></nav>`;}
function adminShell(content){return `<div class="admin-app">${panelTop()}<div class="admin-layout">${panelNav()}<main class="admin-main" id="main">${content}</main></div><footer class="admin-footer"><span>Jogo de Cintura · gestão editorial</span><span>Conteúdo sincronizado com o banco da redação</span></footer></div>`;}
function panelHeading(kicker,title,deck='',action=''){return `<div class="panel-page-heading"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1>${deck?`<p>${deck}</p>`:''}</div>${action}</div>`;}
function roleArticles(){return db.role==='editor'?db.articles:db.role==='autor'?db.articles.filter(a=>a.authorId==='bia-santos'):db.articles.filter(a=>a.status==='em revisão');}
function renderLogin(tab='visao'){
 panelState.tab=tab;document.title='Acesso editorial | Jogo de Cintura';
 document.getElementById('app').innerHTML=`<main class="login-screen" id="main"><section class="login-brand-panel"><a class="login-brand" href="#">${brand()}</a><span class="eyebrow">JOGO DE CINTURA · REDAÇÃO</span><h1>Ideias em movimento.<br><em>Publicação com intenção.</em></h1><p>Organize matérias, acompanhe revisões e mantenha o portal em movimento em um só espaço.</p><div class="login-orbit" aria-hidden="true"><span></span><i></i></div></section><section class="login-form-panel"><a class="back-link" href="#">← Voltar ao portal</a><div class="login-form-wrap"><span class="eyebrow">ÁREA RESTRITA</span><h2>Entrar no painel</h2><p>Use seu e-mail administrativo para acessar o espaço de publicação.</p><form id="access-form"><label for="admin-email">E-mail administrativo</label><input id="admin-email" name="email" type="email" autocomplete="username" inputmode="email" required placeholder="seu@email.com"><label for="admin-password">Senha administrativa</label><input id="admin-password" name="password" type="password" autocomplete="current-password" required minlength="8" placeholder="Digite sua senha"><p class="login-error" id="login-error" role="alert" aria-live="polite"></p><button class="button button-primary" type="submit">Acessar redação ${ico('arrow')}</button></form><small class="login-security">Acesso protegido · dados sincronizados entre dispositivos</small></div></section></main>`;
 const form=document.getElementById('access-form');
 form.addEventListener('submit',async e=>{
  e.preventDefault();const button=form.querySelector('button');button.disabled=true;button.textContent='Verificando acesso…';
  try{const values=new FormData(form);const result=await api('login',{method:'POST',body:JSON.stringify({email:values.get('email'),password:values.get('password')})});accessToken=result.token;localStorage.setItem(TOKEN_KEY,accessToken);await hydrateContent(true);renderPanel(panelState.tab);}
  catch(error){const message=document.getElementById('login-error');if(message)message.textContent=error.message;button.disabled=false;button.innerHTML=`Acessar redação ${ico('arrow')}`;form.elements.password.value='';form.elements.password.focus();}
 });
}
function renderDashboard(){
 const ownArticles=roleArticles();const counts=Object.fromEntries(['rascunho','em revisão','aprovado','publicado','devolvido','agendado'].map(s=>[s,ownArticles.filter(a=>a.status===s).length]));
 const recent=[...ownArticles].sort((a,b)=>(b.history?.at(-1)?.at||'').localeCompare(a.history?.at(-1)?.at||'')).slice(0,5);
 const stages=[['Rascunhos','rascunho'],['Em revisão','em revisão'],['Aprovados','aprovado'],['Publicados','publicado']];
 const today=new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'2-digit',month:'long'}).format(new Date());
 const lead=published()[0];
 const nextAction=counts['em revisão']?['Revisões aguardando','Abra a fila e registre a próxima decisão editorial.','#painel/revisoes']:counts.aprovado?['Pautas prontas para publicar','Revise o acabamento final e escolha a próxima publicação.','#painel/artigos']:['Uma nova pauta começa aqui','Crie uma história com contexto, imagem e um ponto de vista próprio.','#painel/artigos'];
 return `${panelHeading(today.toLocaleUpperCase('pt-BR'),'Bom trabalho, redação.','Uma visão viva da edição: o que avançou, o que precisa de atenção e o que já chegou aos leitores.',`<div class="dashboard-actions"><button class="button button-primary" id="new-article">${ico('plus')} Nova matéria</button></div>`)}
 <section class="dashboard-welcome"><div class="welcome-copy"><span class="eyebrow">A edição em movimento</span><h2>Conteúdo com intenção.<br><em>Publicação com ritmo.</em></h2><p>Seu espaço editorial está conectado ao portal e pronto para transformar pauta em conversa.</p><a class="welcome-link" href="#painel/artigos">Explorar a redação ${ico('arrow')}</a></div><div class="welcome-visual">${lead?`<img src="${esc(lead.cover)}.webp" alt="" loading="lazy"><span class="welcome-image-wash"></span><div class="welcome-story"><small>NO AR · ${esc(lead.category)}</small><strong>${esc(lead.title)}</strong><a href="#artigo/${esc(lead.slug)}" target="_blank" rel="noopener">Ver no portal ${ico('arrow')}</a></div>`:`<span class="welcome-empty">JDC</span>`}<span class="welcome-orbit" aria-hidden="true"></span></div></section>
 <section class="stat-grid" aria-label="Resumo editorial">${stages.map(([label,key],i)=>`<a class="stat-card stat-${i}" href="#painel/${key==='em revisão'?'revisoes':'artigos'}"><span>${label}</span><strong>${counts[key]}</strong><small>${key==='publicado'?'histórias no portal':'pautas nesta etapa'}</small><i>${String(i+1).padStart(2,'0')}</i><b class="stat-arrow">${ico('arrow')}</b></a>`).join('')}</section>
 <div class="dashboard-columns"><section class="editorial-pulse"><div class="subsection-head"><div><span class="eyebrow">Ritmo de produção</span><h2>Esteira editorial</h2></div><a href="#painel/fluxo">Ver o fluxo ${ico('arrow')}</a></div><div class="pipeline">${stages.map(([label,key],i)=>`<a class="pipeline-step" href="#painel/${key==='em revisão'?'revisoes':'artigos'}"><div class="pipeline-top"><span>${String(i+1).padStart(2,'0')}</span><b>${counts[key]}</b></div><div class="pipeline-bar"><span style="width:${Math.max(12,Math.min(100,counts[key]*14))}%"></span></div><small>${label}</small></a>`).join('')}</div><p class="dashboard-note">Uma visão rápida das etapas que mantêm a edição em movimento.</p></section><section class="recent-activity"><div class="subsection-head"><div><span class="eyebrow">Movimentações recentes</span><h2>Últimas atualizações</h2></div></div><ul class="activity-list">${recent.map(a=>`<li><span class="activity-pin status-${statusClass(a.status)}"></span><div><a href="#painel/artigos" class="activity-title">${esc(a.title)}</a><small>${statusLabel(a.status)} · ${esc(a.history?.at(-1)?.by||author(a.authorId).name)}</small></div></li>`).join('')}</ul></section></div>
 <section class="dashboard-next"><div class="next-icon">✳</div><div><span class="eyebrow">Próximo movimento</span><h2>${nextAction[0]}</h2><p>${nextAction[1]}</p></div><a class="button button-outline" href="${nextAction[2]}">Abrir agora ${ico('arrow')}</a></section>
 <section class="quick-start"><div><span class="eyebrow">Espaço de criação</span><h2>Uma pauta muda de mãos.<br>O histórico acompanha.</h2></div><p>Escreva, organize temas, cuide da imagem e acompanhe cada revisão até chegar aos leitores.</p><a class="button button-outline" href="#painel/revisoes">Abrir fila de revisão ${ico('arrow')}</a></section>`;
}
function articleAdminCard(a){const au=author(a.authorId);const own=a.authorId==='bia-santos';return `<article class="admin-article-card"><div class="admin-thumb"><img src="${esc(a.cover)}.webp" alt="" loading="lazy"></div><div class="admin-card-body"><div class="admin-card-top"><span class="status-pill status-${statusClass(a.status)}">${statusLabel(a.status)}</span><span class="admin-category">${esc(a.category)}</span><span class="admin-date">${dateBR(a.date)}</span></div><h3>${esc(a.title)}</h3><p>${esc(a.excerpt)}</p><div class="admin-meta-line"><span>${esc(au.name)}</span><span>· ${a.minutes} min</span><span>· ${a.tags.map(esc).join(', ')}</span></div>${a.status==='agendado'?`<div class="schedule-note">Publicação prevista para <strong>${esc(new Date(a.scheduledAt).toLocaleString('pt-BR'))}</strong>. Confirme a publicação pelo painel.</div>`:''}
  ${(a.comments||[]).length||(a.history||[]).length>1?`<details class="revision-details"><summary>${(a.comments||[]).length} comentário${(a.comments||[]).length===1?'':'s'} de revisão · histórico</summary><div class="revision-log">${(a.comments||[]).map(c=>`<p><strong>${esc(c.by)}</strong> <time>${new Date(c.at).toLocaleString('pt-BR')}</time><br>${esc(c.text)}</p>`).join('')}${(a.history||[]).map(h=>`<p class="history-line"><span class="status-pill status-${statusClass(h.status)}">${statusLabel(h.status)}</span> ${esc(h.by)} · ${new Date(h.at).toLocaleString('pt-BR')}</p>`).join('')}</div></details>`:''}
  <div class="admin-actions">${canEdit(a)?`<button class="button button-small button-outline" data-edit="${a.id}">Editar</button>`:''}${db.role==='autor'&&own&&['rascunho','devolvido'].includes(a.status)?`<button class="button button-small button-primary" data-action="submit" data-id="${a.id}">Enviar para revisão ${ico('arrow')}</button>`:''}${db.role!=='autor'&&a.status==='em revisão'?`<div class="review-action"><label class="sr-only" for="comment-${a.id}">Comentário de revisão para ${esc(a.title)}</label><textarea id="comment-${a.id}" data-comment="${a.id}" placeholder="Comentário para o autor (opcional)"></textarea><button class="button button-small button-outline" data-action="return" data-id="${a.id}">Devolver</button><button class="button button-small button-primary" data-action="approve" data-id="${a.id}">Aprovar ${ico('check')}</button></div>`:''}${db.role==='editor'&&a.status==='aprovado'?`<button class="button button-small button-primary" data-action="publish" data-id="${a.id}">Publicar agora</button><label class="schedule-input">Agendar <input type="datetime-local" data-schedule="${a.id}" aria-label="Data e hora de publicação de ${esc(a.title)}"></label><button class="button button-small button-outline" data-action="schedule" data-id="${a.id}">Confirmar horário</button>`:''}${db.role==='editor'&&a.status==='agendado'?`<button class="button button-small button-primary" data-action="publish" data-id="${a.id}">Publicar agora</button>`:''}${db.role==='editor'?`<button class="icon-button danger-action" data-action="delete" data-id="${a.id}" aria-label="Excluir ${esc(a.title)}">×</button>`:''}</div></div></article>`;}
function renderArticles(reviewOnly=false){const statuses=['todos','rascunho','em revisão','aprovado','devolvido','publicado','agendado'];let list=db.articles.filter(visibleToRole);if(reviewOnly)list=list.filter(a=>a.status==='em revisão');if(panelState.status!=='todos')list=list.filter(a=>a.status===panelState.status);if(panelState.search){const q=panelState.search.toLocaleLowerCase('pt-BR');list=list.filter(a=>`${a.title} ${a.excerpt} ${a.category} ${a.tags.join(' ')}`.toLocaleLowerCase('pt-BR').includes(q));}const statusCount=statuses.slice(1).map(s=>[s,list.filter(a=>a.status===s).length]);return `${panelHeading(reviewOnly?'ETAPA EDITORIAL':'CONTEÚDO','Matérias',reviewOnly?'Pautas aguardando leitura crítica, comentário e decisão.':'Cada pauta em um cartão próprio, com capa, contexto e ações editoriais no mesmo lugar.',db.role!=='revisor'?`<button class="button button-primary" id="new-article">${ico('plus')} Nova matéria</button>`:'')}<div class="editorial-count-strip">${statusCount.map(([s,n])=>`<button class="count-chip ${panelState.status===s?'active':''}" data-quick-status="${esc(s)}"><span class="count-dot status-${statusClass(s)}"></span>${statusLabel(s)}<b>${n}</b></button>`).join('')}</div><div class="list-toolbar"><label class="admin-search">${ico('search')}<span class="sr-only">Buscar no painel</span><input id="admin-search" type="search" placeholder="Buscar por título, categoria ou tag" value="${esc(panelState.search)}"></label><label class="status-select"><span>Etapa</span><select id="status-filter">${statuses.map(s=>`<option value="${esc(s)}" ${panelState.status===s?'selected':''}>${s==='todos'?'Todas as etapas':statusLabel(s)}</option>`).join('')}</select></label><span class="list-count">${list.length} ${list.length===1?'matéria':'matérias'}</span></div><div class="admin-article-list">${list.length?list.map(articleAdminCard).join(''):`<div class="admin-empty"><div class="empty-mark">${ico('book')}</div><h2>Nenhuma matéria nesta etapa</h2><p>Ajuste os filtros ou crie uma nova matéria para esta etapa.</p></div>`}</div>`;}
function renderAuthors(){return `${panelHeading('PESSOAS','Autores','Gerencie os perfis de autoria exibidos nas matérias publicadas.') }<div class="author-admin-grid">${db.authors.map(a=>`<form class="author-admin-card" data-author-save="${esc(a.id)}"><div class="author-card-head"><span class="author-avatar">${esc(a.avatar)}</span><span><strong>${esc(a.name)}</strong><small>${esc(a.title)}</small></span></div><label>Nome<input name="name" required value="${esc(a.name)}"></label><label>Função editorial<input name="title" required value="${esc(a.title)}"></label><label>Biografia<textarea name="bio" rows="3">${esc(a.bio)}</textarea></label><button class="button button-small button-outline">Salvar autor</button></form>`).join('')}</div><form class="add-entity-form" id="add-author-form"><div><span class="eyebrow">Ampliar a redação</span><h2>Adicionar autor</h2></div><input name="name" placeholder="Nome do autor" required><input name="title" placeholder="Função editorial" required><input name="bio" placeholder="Biografia breve" required><button class="button button-primary">Adicionar ${ico('plus')}</button></form>`;}
function renderTaxonomies(){return `${panelHeading('ORGANIZAÇÃO','Categorias e tags','Cadastre, edite e remova termos de organização. Categorias em uso precisam ser reclassificadas antes da exclusão.') }<div class="taxonomy-columns"><section class="taxonomy-panel"><div class="subsection-head"><div><span class="eyebrow">Navegação</span><h2>Categorias</h2></div><strong>${db.categories.length}</strong></div><form id="add-category-form" class="inline-add"><label class="sr-only" for="category-name">Nova categoria</label><input id="category-name" name="name" required placeholder="Nova categoria"><button class="button button-primary button-small">Adicionar</button></form><ul class="taxonomy-list">${db.categories.map(c=>`<li><form class="taxonomy-edit" data-rename-category="${esc(c)}"><label class="sr-only" for="cat-${slugify(c)}">Nome da categoria ${esc(c)}</label><input id="cat-${slugify(c)}" name="newName" required value="${esc(c)}"><button class="tax-save">Salvar</button></form><small>${db.articles.filter(a=>a.category===c).length} matérias</small><button data-remove-category="${esc(c)}" aria-label="Remover categoria ${esc(c)}">×</button></li>`).join('')}</ul></section><section class="taxonomy-panel"><div class="subsection-head"><div><span class="eyebrow">Descoberta</span><h2>Tags</h2></div><strong>${db.tags.length}</strong></div><form id="add-tag-form" class="inline-add"><label class="sr-only" for="tag-name">Nova tag</label><input id="tag-name" name="name" required placeholder="Nova tag"><button class="button button-primary button-small">Adicionar</button></form><ul class="taxonomy-list">${db.tags.map(t=>`<li><form class="taxonomy-edit" data-rename-tag="${esc(t)}"><label class="sr-only" for="tag-${slugify(t)}">Nome da tag ${esc(t)}</label><input id="tag-${slugify(t)}" name="newName" required value="${esc(t)}"><button class="tax-save">Salvar</button></form><small>${db.articles.filter(a=>a.tags.includes(t)).length} matérias</small><button data-remove-tag="${esc(t)}" aria-label="Remover tag ${esc(t)}">×</button></li>`).join('')}</ul></section></div>`;}
function renderWorkflow(){const steps=[['01','Rascunho','Autor organiza pauta, resumo, corpo, capa e metadados de busca.','rascunho'],['02','Em revisão','Revisor registra observações e escolhe aprovar ou devolver.','em revisão'],['03','Aprovado','Editor confere a versão final antes de definir a publicação.','aprovado'],['04','Publicado','Matéria entra no portal e aparece na busca e na navegação.','publicado']];return `${panelHeading('COMO FUNCIONA','Da pauta à publicação','Acompanhe a passagem de cada matéria pelas etapas, os comentários de revisão e o histórico de alterações.') }<div class="workflow-notice"><strong>Redação protegida</strong><p>O acesso ao painel exige senha administrativa. As alterações são validadas no servidor e sincronizadas no banco da redação.</p></div><div class="workflow-steps">${steps.map(([n,t,d,s])=>`<article class="workflow-step"><span class="workflow-number">${n}</span><div><span class="status-pill status-${statusClass(s)}">${t}</span><h2>${t}</h2><p>${d}</p></div><span class="workflow-count">${roleArticles().filter(a=>a.status===s).length}<small>matérias</small></span></article>`).join('')}</div><section class="schedule-explainer"><span class="eyebrow">Publicação agendada</span><h2>O horário fica registrado. A publicação é manual.</h2><p>A data e o horário ficam registrados no banco. No momento agendado, a redação deve confirmar a publicação pelo painel.</p></section><div class="workflow-cta"><a class="button button-primary" href="#painel/artigos">Abrir as matérias ${ico('arrow')}</a><a class="button button-outline" href="#painel/revisoes">Ver fila de revisão</a></div>`;}
function renderPanel(tab='visao'){
 if(!accessToken||!adminReady){renderLogin(tab);return;}
 panelState.tab=tab;document.title='Painel editorial | Jogo de Cintura';
 let content=tab==='visao'?renderDashboard():tab==='artigos'?renderArticles(false):tab==='revisoes'?renderArticles(true):tab==='autores'?renderAuthors():tab==='taxonomias'?renderTaxonomies():renderWorkflow();
 document.getElementById('app').innerHTML=adminShell(content);bindPanel();
}
function openArticleDialog(articleId=''){
 const old=db.articles.find(a=>a.id===articleId);if(old&&!canEdit(old)){toast('Este perfil não pode editar esta matéria.');return;}
 const authorId=old?.authorId||(db.role==='autor'?'bia-santos':'lia-costa');
 const allContent=old?old.body.map(([heading,...paragraphs])=>`${heading}\n${paragraphs.join('\n\n')}`).join('\n\n'):'Abertura da matéria.\n\nDesenvolvimento da pauta.\n\nFechamento e próximo passo.';
 const fileOptions=['ai-no-trabalho','negocio-indicadores','pequeno-negocio-caixa','aprendizagem-carreira','logistica-operacao','dados-decisao','lideranca','robotica-industrial','trabalho-remoto','atendimento','energia-transicao','industria','ideia-negocio','cidade'];
 const availableFiles=fileOptions.filter(n=>!db.articles.some(a=>a.id!==articleId&&a.cover===PHOTO(n)));
 if(!old&&!availableFiles.length){toast('Não há outra capa editorial disponível. Adicione novos arquivos de imagem ao acervo do projeto.');return;}
 dialog.innerHTML=`<form id="article-form" method="dialog" class="article-form"><div class="dialog-top"><div><span class="eyebrow">${old?'Edição de pauta':'Nova pauta'}</span><h2 id="dialog-title">${old?'Editar matéria':'Criar matéria'}</h2></div><button type="button" class="dialog-close" aria-label="Fechar">×</button></div><div class="form-grid"><label class="span-2">Título<input name="title" required maxlength="130" value="${esc(old?.title||'')}" placeholder="Qual é a pauta?"></label><label class="span-2">Subtítulo<input name="subtitle" required maxlength="180" value="${esc(old?.subtitle||'')}" placeholder="Uma linha para contextualizar"></label><label class="span-2">Resumo para os cards<textarea name="excerpt" rows="2" required maxlength="240" placeholder="Explique a ideia principal em poucas linhas">${esc(old?.excerpt||'')}</textarea></label><label>Autor<select name="authorId" ${db.role==='autor'?'disabled':''}>${db.authors.map(a=>`<option value="${esc(a.id)}" ${a.id===authorId?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><label>Categoria<select name="category">${db.categories.map(c=>`<option ${old?.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label class="span-2">Tags, separadas por vírgula<input name="tags" value="${esc(old?.tags.join(', ')||'')}" placeholder="Gestão, Dados, Carreira"></label><label class="span-2">Conteúdo<textarea name="content" rows="9" required>${esc(allContent)}</textarea><small>Separe as seções por uma linha em branco. A primeira linha de cada seção vira subtítulo.</small></label><label class="span-2">Fotografia editorial<select name="cover" id="cover-select">${availableFiles.map(n=>`<option value="${n}" ${old?.cover===PHOTO(n)?'selected':''}>${n.replaceAll('-',' ')}</option>`).join('')}</select><small>Capas WebP locais, geradas com aparência fotográfica. Uma capa por matéria para evitar repetição.</small></label><div class="cover-preview span-2"><img id="cover-preview-img" src="${esc(old?.cover||PHOTO(availableFiles[0]))}.webp" alt="Prévia da fotografia editorial selecionada"><span>Prévia da capa selecionada</span></div><label class="span-2">Slug<input name="slug" required value="${esc(old?.slug||'')}" placeholder="slug-da-materia"></label><label class="span-2">Título SEO<input name="seoTitle" maxlength="70" value="${esc(old?.seoTitle||'')}" placeholder="Título para resultados de busca"></label><label class="span-2">Descrição SEO<textarea name="seoDescription" rows="2" maxlength="160" placeholder="Resumo de até 160 caracteres">${esc(old?.seoDescription||'')}</textarea></label></div><div class="dialog-actions"><button type="button" class="button button-outline dialog-cancel">Cancelar</button><button class="button button-primary" type="submit">Salvar rascunho ${ico('check')}</button></div></form>`;
 dialog.showModal();dialog.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.querySelector('.dialog-cancel').addEventListener('click',()=>dialog.close());
 const form=dialog.querySelector('#article-form');
 form.elements.cover.addEventListener('change',()=>{document.getElementById('cover-preview-img').src=`${PHOTO(form.elements.cover.value)}.webp`;});
 form.elements.title.addEventListener('input',()=>{if(!old||!form.elements.slug.dataset.userEdited)form.elements.slug.value=slugify(form.elements.title.value);});
 form.elements.slug.addEventListener('input',()=>form.elements.slug.dataset.userEdited='1');
 form.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(form);const title=fd.get('title').trim();let slug=slugify(fd.get('slug')||title);if(db.articles.some(a=>a.slug===slug&&a.id!==articleId)){toast('Este slug já está em uso. Escolha outro.');return;}
  const sections=String(fd.get('content')).split(/\n\s*\n/).map(x=>x.trim()).filter(Boolean).map((part,i)=>{const lines=part.split('\n').map(x=>x.trim()).filter(Boolean);return [lines[0]||`Parte ${i+1}`,...lines.slice(1)];});
  const tagList=String(fd.get('tags')).split(',').map(t=>t.trim()).filter(Boolean);tagList.forEach(t=>{if(!db.tags.includes(t))db.tags.push(t);});const category=String(fd.get('category'));if(!db.categories.includes(category))db.categories.push(category);
  const existing=db.articles.find(a=>a.id===articleId);const now=new Date().toISOString();const data={...(existing||{}),id:existing?.id||`a${Date.now()}`,slug,title,subtitle:String(fd.get('subtitle')).trim(),excerpt:String(fd.get('excerpt')).trim(),authorId:db.role==='autor'?'bia-santos':String(fd.get('authorId')),category,tags:tagList,date:existing?.date||new Date().toISOString().slice(0,10),minutes:Math.max(1,Math.ceil(String(fd.get('content')).split(/\s+/).length/190)),cover:PHOTO(String(fd.get('cover'))),alt:`Fotografia editorial relacionada à pauta: ${title}`,seoTitle:String(fd.get('seoTitle')).trim()||`${title} | Jogo de Cintura`,seoDescription:String(fd.get('seoDescription')).trim()||String(fd.get('excerpt')).trim(),status:existing?.status||'rascunho',body:sections,history:existing?.history||[{status:'rascunho',by:actorName(),at:now}],comments:existing?.comments||[]};
  if(existing){data.history.push({status:existing.status,by:actorName(),at:now});}db.articles=existing?db.articles.map(a=>a.id===existing.id?data:a):[data,...db.articles];save();dialog.close();toast(existing?'Matéria salva.':'Rascunho criado.');renderPanel(panelState.tab);
 });
}
function bindPanel(){
 
 document.getElementById('new-article')?.addEventListener('click',()=>openArticleDialog());
 document.getElementById('logout-button')?.addEventListener('click',()=>{accessToken='';adminReady=false;localStorage.removeItem(TOKEN_KEY);renderLogin('visao');});
 document.getElementById('admin-search')?.addEventListener('input',e=>{panelState.search=e.target.value;const pos=e.target.selectionStart;renderPanel(panelState.tab);const next=document.getElementById('admin-search');next.focus();next.setSelectionRange(pos,pos);});
 document.getElementById('status-filter')?.addEventListener('change',e=>{panelState.status=e.target.value;renderPanel(panelState.tab);});
 document.querySelectorAll('[data-quick-status]').forEach(b=>b.addEventListener('click',()=>{panelState.status=panelState.status===b.dataset.quickStatus?'todos':b.dataset.quickStatus;renderPanel(panelState.tab);}));
 document.querySelectorAll('[data-edit]').forEach(b=>b.addEventListener('click',()=>openArticleDialog(b.dataset.edit)));
 document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{
  const a=db.articles.find(x=>x.id===b.dataset.id);if(!a)return;const action=b.dataset.action;const comment=document.querySelector(`[data-comment="${a.id}"]`)?.value||'';
  if(action==='submit'&&db.role==='autor'&&a.authorId==='bia-santos'&&['rascunho','devolvido'].includes(a.status))changeStatus(a,'em revisão',comment);
  if(action==='approve'&&db.role!=='autor'&&a.status==='em revisão')changeStatus(a,'aprovado',comment);
  if(action==='return'&&db.role!=='autor'&&a.status==='em revisão')changeStatus(a,'devolvido',comment||'A matéria foi devolvida para ajustes.');
  if(action==='publish'&&db.role==='editor'&&['aprovado','agendado'].includes(a.status))changeStatus(a,'publicado');
  if(action==='schedule'&&db.role==='editor'&&a.status==='aprovado'){const value=document.querySelector(`[data-schedule="${a.id}"]`)?.value;if(!value){toast('Escolha uma data e um horário para agendar.');return;}a.scheduledAt=new Date(value).toISOString();changeStatus(a,'agendado');}
  if(action==='delete'&&db.role==='editor'&&confirm(`Excluir a matéria “${a.title}”?`)){db.articles=db.articles.filter(x=>x.id!==a.id);save();toast('Matéria excluída.');renderPanel(panelState.tab);}
 }));
 document.querySelectorAll('[data-author-save]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();if(db.role!=='editor'){toast('Somente o perfil de editor pode administrar autores.');return;}const a=db.authors.find(x=>x.id===form.dataset.authorSave);if(!a)return;const fd=new FormData(form);a.name=fd.get('name').trim();a.title=fd.get('title').trim();a.bio=fd.get('bio').trim();a.avatar=a.name.split(/\s+/).slice(0,2).map(p=>p[0]).join('').toUpperCase();save();toast('Autor atualizado.');renderPanel('autores');}));
 document.getElementById('add-author-form')?.addEventListener('submit',e=>{e.preventDefault();if(db.role!=='editor'){toast('Somente o perfil de editor pode administrar autores.');return;}const fd=new FormData(e.currentTarget);const name=fd.get('name').trim();const id=slugify(name);if(db.authors.some(a=>a.id===id)){toast('Já existe um autor com esse nome.');return;}db.authors.push({id,name,title:fd.get('title').trim(),bio:fd.get('bio').trim(),avatar:name.split(/\s+/).slice(0,2).map(p=>p[0]).join('').toUpperCase()});save();toast('Autor adicionado.');renderPanel('autores');});
 document.getElementById('add-category-form')?.addEventListener('submit',e=>{e.preventDefault();if(db.role!=='editor'){toast('Somente o perfil de editor pode alterar categorias.');return;}const name=new FormData(e.currentTarget).get('name').trim();if(db.categories.includes(name)){toast('Essa categoria já existe.');return;}db.categories.push(name);save();toast('Categoria criada.');renderPanel('taxonomias');});
 document.getElementById('add-tag-form')?.addEventListener('submit',e=>{e.preventDefault();if(db.role!=='editor'){toast('Somente o perfil de editor pode alterar tags.');return;}const name=new FormData(e.currentTarget).get('name').trim();if(db.tags.includes(name)){toast('Essa tag já existe.');return;}db.tags.push(name);save();toast('Tag criada.');renderPanel('taxonomias');});
 document.querySelectorAll('[data-rename-category]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();if(db.role!=='editor'){toast('Somente o perfil de editor pode alterar categorias.');return;}const old=form.dataset.renameCategory;const next=new FormData(form).get('newName').trim();if(!next||next===old)return;if(db.categories.includes(next)){toast('Essa categoria já existe.');return;}db.categories=db.categories.map(c=>c===old?next:c);db.articles.forEach(a=>{if(a.category===old)a.category=next;});save();toast('Categoria atualizada.');renderPanel('taxonomias');}));
 document.querySelectorAll('[data-rename-tag]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();if(db.role!=='editor'){toast('Somente o perfil de editor pode alterar tags.');return;}const old=form.dataset.renameTag;const next=new FormData(form).get('newName').trim();if(!next||next===old)return;if(db.tags.includes(next)){toast('Essa tag já existe.');return;}db.tags=db.tags.map(t=>t===old?next:t);db.articles.forEach(a=>{a.tags=a.tags.map(t=>t===old?next:t);});save();toast('Tag atualizada.');renderPanel('taxonomias');}));
 document.querySelectorAll('[data-remove-category]').forEach(b=>b.addEventListener('click',()=>{const name=b.dataset.removeCategory;if(db.role!=='editor'){toast('Somente o perfil de editor pode alterar categorias.');return;}if(db.articles.some(a=>a.category===name)){toast('Reclassifique as matérias antes de remover esta categoria.');return;}if(confirm(`Remover a categoria “${name}”?`)){db.categories=db.categories.filter(c=>c!==name);save();renderPanel('taxonomias');}}));
 document.querySelectorAll('[data-remove-tag]').forEach(b=>b.addEventListener('click',()=>{const name=b.dataset.removeTag;if(db.role!=='editor'){toast('Somente o perfil de editor pode alterar tags.');return;}if(confirm(`Remover “${name}” de todas as matérias e da lista de tags?`)){db.tags=db.tags.filter(t=>t!==name);db.articles.forEach(a=>a.tags=a.tags.filter(t=>t!==name));save();renderPanel('taxonomias');}}));
}
function render(){const hash=decodeURIComponent(location.hash||'');if(hash==='#painel'||hash==='#/painel'){renderPanel('visao');return;}if(hash.startsWith('#painel/')){renderPanel(hash.split('/')[1]||'visao');return;}if(hash.startsWith('#artigo/')){renderArticle(hash.slice('#artigo/'.length));return;}if(hash.startsWith('#autor/')){renderAuthor(hash.slice('#autor/'.length));return;}if(hash.startsWith('#categoria/')){publicState.category=db.categories.find(c=>slugify(c)===hash.split('/')[1])||'';publicState.search='';publicState.tag='';publicState.page=1;renderHome();return;}renderHome();}
window.addEventListener('hashchange',render);
async function bootstrap(){
 try{await hydrateContent(Boolean(accessToken));}
 catch(error){
  if(accessToken){accessToken='';adminReady=false;localStorage.removeItem(TOKEN_KEY);try{await hydrateContent(false);}catch{}}
  if(!db.articles.length){document.getElementById('app').innerHTML=`<main class="service-error"><span class="eyebrow">JOGO DE CINTURA</span><h1>Estamos atualizando a redação.</h1><p>Não foi possível carregar o conteúdo agora. Tente novamente em alguns instantes.</p><button class="button button-primary" id="retry-load">Tentar novamente</button></main>`;document.getElementById('retry-load')?.addEventListener('click',()=>location.reload());}
 }
 render();
}
bootstrap();
